export type RainPlaybackTimeline = {
  frames: readonly RainPlaybackFrame[];
  issuedAt: string;
  expiresAt: string;
};

export function validateRainPlaybackTimeline(
  timeline: RainPlaybackTimeline,
  now: number = Date.now(),
